CREATE TABLE "PublicCollectorProfile" ("userId" TEXT NOT NULL, "slug" TEXT NOT NULL, "headline" TEXT, "specialism" TEXT, "isPublic" BOOLEAN NOT NULL DEFAULT false, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PublicCollectorProfile_pkey" PRIMARY KEY ("userId"));
CREATE UNIQUE INDEX "PublicCollectorProfile_slug_key" ON "PublicCollectorProfile"("slug"); CREATE INDEX "PublicCollectorProfile_isPublic_slug_idx" ON "PublicCollectorProfile"("isPublic", "slug"); ALTER TABLE "PublicCollectorProfile" ADD CONSTRAINT "PublicCollectorProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
CREATE TABLE "WatchlistItem" ("userId" TEXT NOT NULL, "assetId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WatchlistItem_pkey" PRIMARY KEY ("userId", "assetId")); CREATE INDEX "WatchlistItem_userId_createdAt_idx" ON "WatchlistItem"("userId", "createdAt"); ALTER TABLE "WatchlistItem" ADD CONSTRAINT "WatchlistItem_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "WatchlistItem" ADD CONSTRAINT "WatchlistItem_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE RESTRICT;
CREATE TABLE "Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "resourceType" TEXT, "resourceId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "readAt" TIMESTAMP(3), CONSTRAINT "Notification_pkey" PRIMARY KEY ("id")); CREATE INDEX "Notification_userId_readAt_createdAt_id_idx" ON "Notification"("userId", "readAt", "createdAt", "id"); ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
CREATE TABLE "VaultPublicEvent" ("id" TEXT NOT NULL, "assetId" TEXT NOT NULL, "type" TEXT NOT NULL, "occurredAt" TIMESTAMP(3) NOT NULL, "publicSummary" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PUBLISHED', "sourceRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "VaultPublicEvent_pkey" PRIMARY KEY ("id")); CREATE INDEX "VaultPublicEvent_status_occurredAt_id_idx" ON "VaultPublicEvent"("status", "occurredAt", "id"); CREATE INDEX "VaultPublicEvent_assetId_occurredAt_idx" ON "VaultPublicEvent"("assetId", "occurredAt"); ALTER TABLE "VaultPublicEvent" ADD CONSTRAINT "VaultPublicEvent_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE RESTRICT;
